mapper.sql:
AND mo.merchant_id = #{merchantId}
AND m.region = #{region}
AND mo.operator_type = 2
AND mo.is_deleted = FALSE
AND m.is_deleted = FALSE

    AND (
        LOWER(mo.account) LIKE CONCAT('%', LOWER(#{query.keyword}), '%')
        OR LOWER(mo.name) LIKE CONCAT('%', LOWER(#{query.keyword}), '%')
        OR LOWER(mo.email) LIKE CONCAT('%', LOWER(#{query.keyword}), '%')
        OR mo.phone LIKE CONCAT('%', #{query.keyword}, '%')
    )


    AND mo.status = #{query.status}

mapper.select:
SELECT mo.id, mo.merchant_id, mo.account, mo.name, mo.phone, mo.email,
       mo.shop_scope_type, mo.status, mo.created_at, mo.updated_at
FROM merchant_operator mo
JOIN merchant m ON m.id = mo.merchant_id
WHERE mo.id = #{operatorId}
  AND mo.merchant_id = #{merchantId}
  AND m.region = #{region}
  AND mo.operator_type = 2
  AND mo.is_deleted = FALSE
  AND m.is_deleted = FALSE

mapper.update:
UPDATE merchant_operator
SET status = #{status},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{operatorId}
  AND merchant_id = #{merchantId}
  AND operator_type = 2
  AND is_deleted = FALSE
  AND status = #{expectedStatus}
  AND EXISTS (
      SELECT 1 FROM merchant m
      WHERE m.id = merchant_operator.merchant_id
        AND m.region = #{region}
        AND m.is_deleted = FALSE
  )

